import{_ as e,o as t,c as l,a5 as p}from"./chunks/framework.BPFk9-tb.js";const q=JSON.parse('{"title":"写作课作业-084","description":"","frontmatter":{"date":"2020-10-22T19:35:42","title":"写作课作业-084","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/084.md","filePath":"posts/homework/084.md"}'),a={name:"posts/homework/084.md"};function c(u,o,r,i,k,s){return t(),l("div",null,[...o[0]||(o[0]=[p('<blockquote><p>《微信互联网平民创业》之《16. 怎样才能成为受人欢迎的人?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>在「直播带货」的背后，实际上是一个趋势在起作用：</p><blockquote><p>广告业态被解析之后的重构。</p></blockquote><p>……</p><p>让我们继续深入研究下去，问一问下一个问题：</p><blockquote><p>「嗯，广告业态被解析之后又重构了……那这又究竟是为什么呢？」</p></blockquote><p>这个问题的答案就跟平民又明显的关系了：</p><blockquote><p>电商生态终于从「分销时代」正式进入了「直销时代」……</p></blockquote></blockquote><blockquote><p>平日里我们可能用「大受欢迎」就已经表达足够精确了；但是，当我们在这里严肃讨论商业、讨论直销的时候，我宁愿使用这样的措辞：</p><blockquote><p>被很多人人爱！</p></blockquote><p>——是「爱」，是「热爱」，而不仅仅是「喜欢」……因为最终人家是要掏腰包的啊！</p></blockquote><blockquote><p>我这是在给你指路呢！不仅是指路，那路径还格外清晰：</p><ul><li>花一段时间（半年？）剔除掉自己身上的「讨好型人格」；</li><li>花一段时间（半年？）把自己变成「不讨人厌的人」；</li><li>然后，再花一段时间（半年？），成为「竟然有很多人爱的人」……</li></ul></blockquote><blockquote><p>「价值力」和「同理心」就好像是构成一个⻜轮的两个轮桨，再最初的时候，若是想要 让原本静止的⻜轮转动起来，你必须使很大的力气，一圈一圈地反复推，每转一圈都很 费力，但，每一圈的努力都不会白费，⻜轮会转动得越来越快...... 一旦「⻜轮效应」出 现，就再也没有任何力量可以让它停下来。</p></blockquote><blockquote><p>对平⺠来说，开始积累自己的价值力，有个非常简单的起步动作:</p><blockquote><p>每天腾出一点时间精力真诚地在自己的能力范围内帮助他人**......**</p></blockquote></blockquote><blockquote><p>相对于提升自己的「价值力」，提升自己的「同理心」是更容易且收益更大的路径。其 实，提高自己的同理心，也并不难 —— 无非是每天腾出十到三十分钟，问自己几个问题，而后耐心回答。</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>身处在一个分布式的世界而不自知。</p><p>在俞军《产品方法论》中也特别强调同理心，其中也说到，同理心在相当程度上也可以通过后天训练加强。最基础的一点就是亲自实践，去体验自己的产品，通过多角度的亲历，了解用户的需求。而在这里，也强调同理心也是可以习得的，而非一成不变的，并且也提供了如何习得的方法，并且通过问题的方式让同理心的习得更可能落地。</p><p>对待家人，最近有点急躁，为什么呢？不就是被说中了，赚不到啥钱，还事儿多，并且竟然还有一大堆没必要的自尊。</p><p>在自己的能力范围内帮助他人，有时自己就考虑不好这个度，自己还是泥菩萨的时候想帮助他人，结果也没帮好，他人不满意，自己也不满意。</p><p>在这之前应该把自己变得更好，更有能力。</p>',14)])])}const n=e(a,[["render",c]]);export{q as __pageData,n as default};
